parameters.query:
SELECT email, lang
FROM unsubscribe_tokens
WHERE token = $1;

INSERT INTO email_suppression (email, reason, source)
VALUES ($1, 'user_unsubscribe',
        (SELECT source FROM unsubscribe_tokens WHERE token = $2))
ON CONFLICT (email) DO NOTHING;
UPDATE unsubscribe_tokens SET used_at = now()
WHERE token = $2 AND used_at IS NULL;

