// Builds the confirmation page in the recipient's own language.
//
// FIXED September 6, 2026: this read `$json`, whose upstream node is
// `Record Suppression` -- a Postgres INSERT/UPDATE. That node outputs the
// QUERY RESULT, not the row, so `email` and `lang` were both undefined and
// every page rendered in the Spanish fallback with a blank address. The write
// side was correct throughout, which is exactly why it was invisible: the
// suppression row landed, `used_at` was set, and only the page was wrong.
// Read the row from `Lookup Token` by name, never from whatever happens to be
// upstream.
//
// FIXED AGAIN, same day: this node was `runOnceForEachItem` while the code
// returned an ARRAY, which that mode does not accept -- and `.item` needs
// item pairing that an INSERT node upstream does not carry. It emitted no
// `html`, so the Respond node returned HTTP 200 with an EMPTY BODY: status
// fine, database fine, page blank. Now runs once for all items and reads
// `.first()`.

const row = $('Lookup Token').first().json || {};
const lang = (row.lang || 'SPANISH').toUpperCase();

const COPY = {
  SPANISH: {
    title: 'Listo, te diste de baja',
    body: 'No vas a recibir más correos de Triaperformance en esta dirección.',
    note: 'Si fue un error o querés volver a recibirlos, escribime a coach@triaperformance.com y lo revierto.',
    sign: 'Iván Koch — Triaperformance',
  },
  ENGLISH: {
    title: "You're unsubscribed",
    body: 'You will not receive any more emails from Triaperformance at this address.',
    note: 'If this was a mistake, or you want them back, write to coach@triaperformance.com and I will undo it.',
    sign: 'Iván Koch — Triaperformance',
  },
  PORTUGUESE: {
    title: 'Pronto, você foi descadastrado',
    body: 'Você não vai receber mais emails da Triaperformance neste endereço.',
    note: 'Se foi um engano, ou se quiser voltar a receber, escreva para coach@triaperformance.com que eu reverto.',
    sign: 'Iván Koch — Triaperformance',
  },
};

const t = COPY[lang] || COPY.SPANISH;
const esc = (s) => String(s).replace(/[&<>"]/g, (c) =>
  ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));

const html = `<!doctype html>
<html lang="${lang === 'PORTUGUESE' ? 'pt' : lang === 'ENGLISH' ? 'en' : 'es'}">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow">
<title>${esc(t.title)}</title>
<style>
  :root { color-scheme: light; }
  body { margin:0; min-height:100vh; display:grid; place-items:center;
         background:#f6f7f9; color:#14202e;
         font:16px/1.6 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif; }
  .card { max-width:32rem; margin:1.5rem; padding:2.5rem 2rem; background:#fff;
          border-radius:14px; box-shadow:0 1px 3px rgba(20,32,46,.10); }
  h1 { margin:0 0 .75rem; font-size:1.35rem; letter-spacing:-.01em; }
  p { margin:0 0 1rem; }
  .email { font-weight:600; }
  .note { color:#5a6a7d; font-size:.9rem; }
  .sign { margin:1.5rem 0 0; padding-top:1rem; border-top:1px solid #e6e9ee;
          color:#5a6a7d; font-size:.85rem; }
  a { color:#0f6f5c; }
</style>
</head>
<body>
  <main class="card">
    <h1>${esc(t.title)}</h1>
    <p>${esc(t.body)}<br><span class="email">${esc(row.email || '')}</span></p>
    <p class="note">${esc(t.note)}</p>
    <p class="sign">${esc(t.sign)}</p>
  </main>
</body>
</html>`;

return [{ json: { html } }];
